extension CommandPlacement {
    /// Masque les fenêtres `ids` vivantes sur l'écran de la commande. O(k).
    mutating func hide(_ ids: some Sequence<WindowID>, windowsByID: [WindowID: WindowSnapshot], on display: DisplaySnapshot, among displays: [DisplaySnapshot]) {
        for id in ids {
            guard let window = windowsByID[id] else { continue }
            hiding[id] = HiddenWindowPlacement.frame(for: window.frame.cgRect, on: display, among: displays)
        }
    }

    /// Restaure les frames mémorisées des membres vivants. O(m).
    mutating func restoreMembers(of stage: RoadieStages.StageState?, windowsByID: [WindowID: WindowSnapshot]) {
        for member in stage?.members ?? [] where windowsByID[member.windowID] != nil {
            restoring[member.windowID] = member.frame.cgRect
        }
    }
}

